-- Bring Shopify product type into the V2 catalog category field.
create or replace function public.sync_shopify_catalog_categories(p_catalog jsonb) returns integer language plpgsql security invoker set search_path=pg_catalog,public as $$ declare v_count integer; begin if jsonb_typeof(p_catalog)<>'array' then raise exception 'catalog payload must be an array';end if;with catalog as (select distinct on (upper(trim(item->>'sku'))) upper(trim(item->>'sku')) sku_key,nullif(trim(item->>'category'),'') category from jsonb_array_elements(p_catalog)item where nullif(trim(item->>'sku'),'') is not null order by upper(trim(item->>'sku'))) update public.products p set category=c.category,updated_at=now() from catalog c where upper(trim(p.sku))=c.sku_key and p.category is distinct from c.category;get diagnostics v_count=row_count;return v_count;end $$;
revoke all on function public.sync_shopify_catalog_categories(jsonb) from public,anon,authenticated; grant execute on function public.sync_shopify_catalog_categories(jsonb) to service_role;